{
  "tasks": [
    {
      "task_id": "T01",
      "title": "销售数据整体概况",
      "business_question": "这份销售数据的总体规模、订单状态分布及销售额汇总情况如何？",
      "priority": "P0",
      "priority_reason": "探索性分析的基础，提供数据集的全局视图（行数、唯一订单数、总销售额、平均销售额），是理解主要特征的前提。删除后无法回答核心问题中的“主要特征”。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_rows"
              },
              {
                "function": "distinct_count",
                "field": "field_0006",
                "alias": "unique_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales_amount"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_sales_amount"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "地区与城市维度差异分析",
      "business_question": "不同地区和城市的销售表现（订单量与销售额）有何差异？",
      "priority": "P0",
      "priority_reason": "探索“主要差异”的核心任务。通过分组聚合揭示地理维度的分布特征，直接支持业务目标中关于差异的探索。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_sum"
              }
            ],
            "dimensions": [
              "field_0002",
              "field_0003"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "产品类别销售贡献分析",
      "business_question": "各产品类别的销售数量与销售金额占比情况如何？",
      "priority": "P1",
      "priority_reason": "补充性分析，进一步细化“主要特征”，从产品维度揭示数据结构。虽非绝对核心（如仅看地域可能已足够），但对完整探索数据特征有价值。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "category_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "category_sales_sum"
              }
            ],
            "dimensions": [
              "field_0007"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T04",
      "title": "时间趋势初步观察",
      "business_question": "按月份统计的销售额和订单数分布如何？",
      "priority": "P2",
      "priority_reason": "基于现有日期字段进行时间维度的简单切片，属于探索性分析中的常见视角，用于发现潜在的时间规律，但优先级低于核心结构分析。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "derive",
          "params": {
            "function": "extract_month",
            "field": "field_0001",
            "alias": "order_month"
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "monthly_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "monthly_sales_sum"
              }
            ],
            "dimensions": [
              "order_month"
            ]
          }
        }
      ]
    }
  ]
}
